const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    const root_module = b.createModule(.{
        .root_source_file = b.path("src/main.zig"),
        .target = target,
        .optimize = optimize,
    });

    const exe = b.addExecutable(.{ .name = "app", .root_module = root_module });
    b.installArtifact(exe);

    const run_cmd = b.addRunArtifact(exe);
    run_cmd.step.dependOn(b.getInstallStep());
    b.step("run", "Run the LRU simulator").dependOn(&run_cmd.step);

    const tests = b.addTest(.{ .root_module = root_module });
    b.step("test", "Run unit tests").dependOn(&b.addRunArtifact(tests).step);
}

//! A least-recently-used cache mapping byte-string keys to byte-string values.
//!
//! Entries are stored densely in an array hash map and threaded, by entry
//! index, into a doubly linked recency list (head = least recently used,
//! tail = most recently used). Removal swaps the last entry into the vacated
//! slot and patches its neighbours' links. The map deletes without
//! tombstones, so lookup cost stays flat under heavy insert/delete churn.
//! Every operation runs in O(1) expected time.
//!
//! The cache does not own key or value memory: slices passed to `put` must
//! outlive the cache (or their entry).

const std = @import("std");
const Allocator = std.mem.Allocator;

const Lru = @This();

const Index = u32;
const none: Index = std.math.maxInt(Index);

const Entry = struct {
    value: []const u8,
    prev: Index,
    next: Index,
};

map: std.StringArrayHashMapUnmanaged(Entry) = .empty,
head: Index = none,
tail: Index = none,
capacity: usize,

pub fn init(capacity: usize) Lru {
    return .{ .capacity = capacity };
}

pub fn deinit(self: *Lru, gpa: Allocator) void {
    self.map.deinit(gpa);
    self.* = undefined;
}

/// Pre-allocates room for `n` entries so that inserts up to that count do not
/// reallocate.
pub fn ensureTotalCapacity(self: *Lru, gpa: Allocator, n: usize) Allocator.Error!void {
    try self.map.ensureTotalCapacity(gpa, n);
}

pub fn count(self: *const Lru) usize {
    return self.map.count();
}

/// Returns the value for `key` and marks it most recently used.
pub fn get(self: *Lru, key: []const u8) ?[]const u8 {
    const index = self.map.getIndex(key) orelse return null;
    self.touch(@intCast(index));
    return self.entries()[index].value;
}

/// Inserts or overwrites `key`, marking it most recently used. Evicts the
/// least recently used entry if the cache then exceeds its capacity.
pub fn put(self: *Lru, gpa: Allocator, key: []const u8, value: []const u8) Allocator.Error!void {
    if (self.capacity == 0) return;
    if (self.map.count() >= none) return error.OutOfMemory;

    const gop = try self.map.getOrPut(gpa, key);
    const index: Index = @intCast(gop.index);
    if (gop.found_existing) {
        gop.value_ptr.value = value;
        self.touch(index);
        return;
    }

    gop.value_ptr.* = .{ .value = value, .prev = none, .next = none };
    self.pushBack(index);

    if (self.map.count() > self.capacity) {
        std.debug.assert(self.head != index);
        self.removeAt(self.head);
    }
}

/// Removes `key`; returns whether it was present.
pub fn remove(self: *Lru, key: []const u8) bool {
    const index = self.map.getIndex(key) orelse return false;
    self.removeAt(@intCast(index));
    return true;
}

fn entries(self: *const Lru) []Entry {
    return self.map.values();
}

fn removeAt(self: *Lru, index: Index) void {
    self.unlink(index);
    const last: Index = @intCast(self.map.count() - 1);
    self.map.swapRemoveAt(index);
    if (index == last) return;

    // The former last entry now lives at `index`; redirect links to it.
    const nodes = self.entries();
    const moved = nodes[index];
    if (moved.prev != none) nodes[moved.prev].next = index else self.head = index;
    if (moved.next != none) nodes[moved.next].prev = index else self.tail = index;
}

fn touch(self: *Lru, index: Index) void {
    if (index == self.tail) return;
    self.unlink(index);
    self.pushBack(index);
}

fn unlink(self: *Lru, index: Index) void {
    const nodes = self.entries();
    const node = &nodes[index];
    if (node.prev != none) nodes[node.prev].next = node.next else self.head = node.next;
    if (node.next != none) nodes[node.next].prev = node.prev else self.tail = node.prev;
    node.prev = none;
    node.next = none;
}

fn pushBack(self: *Lru, index: Index) void {
    const nodes = self.entries();
    nodes[index].prev = self.tail;
    nodes[index].next = none;
    if (self.tail != none) nodes[self.tail].next = index else self.head = index;
    self.tail = index;
}

const testing = std.testing;

test "evicts least recently used" {
    var lru: Lru = .init(2);
    defer lru.deinit(testing.allocator);

    try lru.put(testing.allocator, "a", "1");
    try lru.put(testing.allocator, "b", "2");
    try testing.expectEqualStrings("1", lru.get("a").?);
    try lru.put(testing.allocator, "c", "3");
    try testing.expectEqual(null, lru.get("b"));
    try testing.expectEqualStrings("1", lru.get("a").?);
    try testing.expectEqualStrings("3", lru.get("c").?);
    try testing.expectEqual(2, lru.count());
}

test "overwrite refreshes recency" {
    var lru: Lru = .init(2);
    defer lru.deinit(testing.allocator);

    try lru.put(testing.allocator, "a", "1");
    try lru.put(testing.allocator, "b", "2");
    try lru.put(testing.allocator, "a", "9");
    try lru.put(testing.allocator, "c", "3");
    try testing.expectEqualStrings("9", lru.get("a").?);
    try testing.expectEqual(null, lru.get("b"));
}

test "remove keeps recency order of moved entries" {
    var lru: Lru = .init(3);
    defer lru.deinit(testing.allocator);

    try lru.put(testing.allocator, "x", "1");
    try lru.put(testing.allocator, "y", "2");
    try lru.put(testing.allocator, "z", "3");
    // Removing "x" moves "z" into its slot; order must stay y, z.
    try testing.expect(lru.remove("x"));
    try testing.expect(!lru.remove("x"));
    try lru.put(testing.allocator, "w", "4");
    try lru.put(testing.allocator, "v", "5");
    try testing.expectEqual(null, lru.get("y"));
    try testing.expectEqualStrings("3", lru.get("z").?);
    try testing.expectEqual(3, lru.count());
}

test "zero capacity holds nothing" {
    var lru: Lru = .init(0);
    defer lru.deinit(testing.allocator);

    try lru.put(testing.allocator, "a", "1");
    try testing.expectEqual(0, lru.count());
    try testing.expectEqual(null, lru.get("a"));
}

//! Simulates an LRU cache driven by commands read from standard input.
//! See SPEC.md for the input format and command semantics.

const std = @import("std");
const Allocator = std.mem.Allocator;
const Lru = @import("Lru.zig");

/// ASCII whitespace as understood by Python's `bytes.split()` and `int()`.
const whitespace = " \t\n\r\x0b\x0c";

pub fn main(init: std.process.Init) !void {
    const gpa = init.gpa;
    const io = init.io;

    var stdin_reader = std.Io.File.stdin().readerStreaming(io, &.{});
    const input = try stdin_reader.interface.allocRemaining(gpa, .unlimited);
    defer gpa.free(input);

    var stdout_buffer: [64 * 1024]u8 = undefined;
    var stdout_writer = std.Io.File.stdout().writer(io, &stdout_buffer);
    const out = &stdout_writer.interface;

    try run(gpa, input, out);
    try out.flush();
}

/// Executes every command in `input`, writing one line per output to `out`.
/// Keys and values in the cache borrow from `input`.
pub fn run(gpa: Allocator, input: []const u8, out: *std.Io.Writer) !void {
    var lines = std.mem.splitScalar(u8, input, '\n');
    const capacity = parseCapacity(lines.first()) orelse return;

    var cache: Lru = .init(capacity);
    defer cache.deinit(gpa);
    // Never more entries than SET commands, so bound the reservation by the line count.
    try cache.ensureTotalCapacity(gpa, @min(capacity, std.mem.count(u8, input, "\n")) + 1);

    while (lines.next()) |line| {
        var tokens = std.mem.tokenizeAny(u8, line, whitespace);
        const cmd = tokens.next() orelse continue;
        switch (Command.parse(cmd) orelse continue) {
            .get => {
                const key = tokens.next() orelse continue;
                try out.print("{s}\n", .{cache.get(key) orelse "NULL"});
            },
            .set => {
                const key = tokens.next() orelse continue;
                const value = tokens.next() orelse continue;
                try cache.put(gpa, key, value);
            },
            .del => {
                const key = tokens.next() orelse continue;
                try out.writeAll(if (cache.remove(key)) "1\n" else "0\n");
            },
            .size => try out.print("{d}\n", .{cache.count()}),
        }
    }
}

const Command = enum {
    get,
    set,
    del,
    size,

    const map: std.StaticStringMap(Command) = .initComptime(.{
        .{ "GET", .get },
        .{ "SET", .set },
        .{ "DEL", .del },
        .{ "SIZE", .size },
    });

    fn parse(token: []const u8) ?Command {
        return map.get(token);
    }
};

/// Parses the capacity line with Python `int()` rules: surrounding whitespace,
/// an optional sign, and single underscores between digits are accepted.
/// Negative values clamp to 0 and oversized values saturate. Returns null if
/// the line is not an integer.
fn parseCapacity(line: []const u8) ?usize {
    var digits = std.mem.trim(u8, line, whitespace);
    var negative = false;
    if (digits.len > 0 and (digits[0] == '+' or digits[0] == '-')) {
        negative = digits[0] == '-';
        digits = digits[1..];
    }
    if (digits.len == 0) return null;

    var value: usize = 0;
    var prev_digit = false;
    for (digits) |c| switch (c) {
        '0'...'9' => {
            value = std.math.mul(usize, value, 10) catch std.math.maxInt(usize);
            value = std.math.add(usize, value, c - '0') catch std.math.maxInt(usize);
            prev_digit = true;
        },
        '_' => {
            if (!prev_digit) return null;
            prev_digit = false;
        },
        else => return null,
    };
    if (!prev_digit) return null;
    return if (negative) 0 else value;
}

fn expectOutput(input: []const u8, expected: []const u8) !void {
    var buf: std.Io.Writer.Allocating = .init(std.testing.allocator);
    defer buf.deinit();
    try run(std.testing.allocator, input, &buf.writer);
    try std.testing.expectEqualStrings(expected, buf.written());
}

test "spec example" {
    try expectOutput("2\nSET a 1\nSET b 2\nGET a\nSET c 3\nGET b\nSIZE\n", "1\nNULL\n2\n");
}

test "del and size without trailing newline" {
    try expectOutput("3\nSET x 1\nDEL x\nDEL x\nSIZE\nGET x", "1\n0\n0\nNULL\n");
}

test "blank lines, CRLF and unknown commands are ignored" {
    try expectOutput("1\r\n\nSET a 1\r\nNOPE\n  \nGET a\r\n", "1\n");
}

test "invalid capacity produces no output" {
    try expectOutput("x\nSIZE\n", "");
    try expectOutput("", "");
}

test "parseCapacity follows Python int()" {
    try std.testing.expectEqual(5, parseCapacity(" +5 \r"));
    try std.testing.expectEqual(1000, parseCapacity("1_000"));
    try std.testing.expectEqual(0, parseCapacity("-3"));
    try std.testing.expectEqual(null, parseCapacity("1__0"));
    try std.testing.expectEqual(null, parseCapacity("_1"));
    try std.testing.expectEqual(null, parseCapacity("1_"));
    try std.testing.expectEqual(null, parseCapacity("-"));
    try std.testing.expectEqual(std.math.maxInt(usize), parseCapacity("99999999999999999999999"));
}

test {
    _ = Lru;
}
